import re
for root,dirs,files in os.walk('.'):
    dirs[:] = [d for d in dirs if d!='__pycache__']
    for f in files:
        p=os.path.join(root,f)
        try: t=open(p,encoding='utf-8',errors='replace').read()
        except: continue
        for i,l in enumerate(t.splitlines(),1):
            if re.search(r'PAGE',l):
                print(p,i,repr(l))
